          const saved=JSON.parse(normalSnapshot);
          if(saved.version!==1||!validPermutation(saved.goal)||!validPermutation(saved.values)||!Number.isSafeInteger(saved.moves)||saved.moves<0||!Number.isSafeInteger(saved.wins)||saved.wins<0)throw Error('invalid record');
          puzzle={goal:saved.goal,targets:swapSums(saved.goal),values:saved.values};wins=saved.wins;
