      if(finished){const won=progress.answer.every((v,i)=>v===state.puzzle.order[i]);status.textContent=won?`正解！ ${progress.count}回くらべたよ`:`おしい！ 答え：${state.puzzle.order.map(i=>names[i]).join(' → ')}（${progress.count}回）`;if(won)offerCopy(`くらべて順番${level==='normal'?'':` ${labels[level]}`}${daily?` ${date}`:''} ${progress.count}回で正解\nhttps://game.kihamda.net/play-balance.html${daily?`?mode=daily&difficulty=${level}&version=1`:''}`)}
